function ThrowMode($il,$mode,[int]$value){$next=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,$value);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$next);$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'buffer failure');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$il.MarkLabel($next)}

function ThrowArgumentMode($il,$mode,[int]$value,[string]$parameter){$next=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,$value);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$next);$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'callback argument failure');if($parameter -eq '~'){$il.Emit([Reflection.Emit.OpCodes]::Ldnull)}else{$il.Emit([Reflection.Emit.OpCodes]::Ldstr,$parameter)};$il.Emit([Reflection.Emit.OpCodes]::Newobj,[ArgumentException].GetConstructor([type[]]@([string],[string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$il.MarkLabel($next)}
function CustomType([string]$Direction){
 $base=[type]("System.Text.${Direction}Fallback");$buffer=[type]("System.Text.${Direction}FallbackBuffer");$builder=$module.DefineType('Buffer'+$Direction,[Reflection.TypeAttributes]::Public,$buffer);[void]$builder.DefineDefaultConstructor([Reflection.MethodAttributes]::Public)
 $output=$builder.DefineField('Output',[string],[Reflection.FieldAttributes]::Public);$position=$builder.DefineField('Position',[int],[Reflection.FieldAttributes]::Public);$mode=$builder.DefineField('Mode',[int],[Reflection.FieldAttributes]::Public)
 $metrics=@{};foreach($name in @('NextCalls','FallbackCalls','RemainingCalls','MoveCalls','ResetCalls')){$metrics[$name]=$builder.DefineField($name,[int],[Reflection.FieldAttributes]'Public,Static')}
