 }
 $m=$builder.DefineMethod('GetNextChar',$attributes,[char],[type[]]@());$il=$m.GetILGenerator();Bump $il $metrics.NextCalls;ThrowMode $il $mode 3;$nonempty=$il.DefineLabel()
 $il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$position);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$output);$il.Emit([Reflection.Emit.OpCodes]::Callvirt,[string].GetProperty('Length').GetMethod);$il.Emit([Reflection.Emit.OpCodes]::Blt,$nonempty);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ret);$il.MarkLabel($nonempty)
 $il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$output);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$position);$il.Emit([Reflection.Emit.OpCodes]::Callvirt,[string].GetProperty('Chars').GetMethod)
 $il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Dup);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$position);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Add);$il.Emit([Reflection.Emit.OpCodes]::Stfld,$position);$il.Emit([Reflection.Emit.OpCodes]::Ret);$builder.DefineMethodOverride($m,$buffer.GetMethod('GetNextChar'))
 $m=$builder.DefineMethod('get_Remaining',$attributes-bor[Reflection.MethodAttributes]::SpecialName,[int],[type[]]@());$il=$m.GetILGenerator();Bump $il $metrics.RemainingCalls;ThrowMode $il $mode 2;$normal=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$normal);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ret);$il.MarkLabel($normal)
 $il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$output);$il.Emit([Reflection.Emit.OpCodes]::Callvirt,[string].GetProperty('Length').GetMethod);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$position);$il.Emit([Reflection.Emit.OpCodes]::Sub);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Call,[Math].GetMethod('Max',[type[]]@([int],[int])));$il.Emit([Reflection.Emit.OpCodes]::Ret);$builder.DefineMethodOverride($m,$buffer.GetProperty('Remaining').GetMethod)
 $m=$builder.DefineMethod('MovePrevious',$attributes,[bool],[type[]]@());$il=$m.GetILGenerator();Bump $il $metrics.MoveCalls;ThrowMode $il $mode 7;$done=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_6);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$done);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Dup);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$position);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Sub);$il.Emit([Reflection.Emit.OpCodes]::Stfld,$position);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Ret);$il.MarkLabel($done);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ret);$builder.DefineMethodOverride($m,$buffer.GetMethod('MovePrevious'))
 $m=$builder.DefineMethod('Reset',$attributes,[void],[type[]]@());$il=$m.GetILGenerator();Bump $il $metrics.ResetCalls;ThrowMode $il $mode 8;$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Call,$buffer.GetMethod('Reset'));$il.Emit([Reflection.Emit.OpCodes]::Ret);$builder.DefineMethodOverride($m,$buffer.GetMethod('Reset'))
 $bufferType=$builder.CreateType();$script:bufferTypes[$Direction]=$bufferType
 $builder=$module.DefineType('Custom'+$Direction+'Fallback',[Reflection.TypeAttributes]::Public,$base);[void]$builder.DefineDefaultConstructor([Reflection.MethodAttributes]::Public);$text=$builder.DefineField('Replacement',[string],[Reflection.FieldAttributes]::Public);$maximum=$builder.DefineField('Maximum',[int],[Reflection.FieldAttributes]::Public);$mode=$builder.DefineField('Mode',[int],[Reflection.FieldAttributes]::Public);$calls=$builder.DefineField('FactoryCalls',[int],[Reflection.FieldAttributes]::Public)
 $getter=$builder.DefineMethod('get_MaxCharCount',$attributes-bor[Reflection.MethodAttributes]::SpecialName,[int],[type[]]@());$il=$getter.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$maximum);$il.Emit([Reflection.Emit.OpCodes]::Ret);$builder.DefineMethodOverride($getter,$base.GetProperty('MaxCharCount').GetMethod)
 $factory=$builder.DefineMethod('CreateFallbackBuffer',$attributes,$buffer,[type[]]@());$il=$factory.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Dup);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$calls);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Add);$il.Emit([Reflection.Emit.OpCodes]::Stfld,$calls)
 $normalFactory=$il.DefineLabel();$nullFactory=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,9);$il.Emit([Reflection.Emit.OpCodes]::Beq,$nullFactory);ThrowMode $il $mode 10;$il.Emit([Reflection.Emit.OpCodes]::Br,$normalFactory);$il.MarkLabel($nullFactory);$il.Emit([Reflection.Emit.OpCodes]::Ldnull);$il.Emit([Reflection.Emit.OpCodes]::Ret);$il.MarkLabel($normalFactory);
 $il.Emit([Reflection.Emit.OpCodes]::Newobj,$bufferType.GetConstructor([type[]]@()));foreach($pair in @(@('Output',$text),@('Mode',$mode))){$il.Emit([Reflection.Emit.OpCodes]::Dup);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$pair[1]);$il.Emit([Reflection.Emit.OpCodes]::Stfld,$bufferType.GetField($pair[0]))};$il.Emit([Reflection.Emit.OpCodes]::Ret);$builder.DefineMethodOverride($factory,$base.GetMethod('CreateFallbackBuffer'));return $builder.CreateType()
}

function Bridge([string]$Direction,[bool]$Write){
 $encoder=$Direction -eq 'Encoder';$owner=[Text.Encoding];$sourceElement=if($encoder){[char]}else{[byte]};$destinationElement=if($encoder){[byte]}else{[char]};$sourceArray=$sourceElement.MakeArrayType();$destinationArray=$destinationElement.MakeArrayType();$readOnly=[type]'System.ReadOnlySpan`1';$span=[type]'System.Span`1';$sourceType=$readOnly.MakeGenericType([type[]]@($sourceElement));$destinationType=$span.MakeGenericType([type[]]@($destinationElement))
 [type[]]$signature=if($Write){@($owner,$sourceArray,[int],[int],$destinationArray,[int],[int],[int[]])}else{@($owner,$sourceArray,[int],[int])};$methodName=if($encoder){if($Write){'TryGetBytes'}else{'GetByteCount'}}else{if($Write){'TryGetChars'}else{'GetCharCount'}};[type[]]$methodSignature=if($Write){@($sourceType,$destinationType,[int].MakeByRefType())}else{@($sourceType)};$method=$owner.GetMethod($methodName,$methodSignature)
 $bridge=[Reflection.Emit.DynamicMethod]::new('EncodingTry'+$Direction+$Write,[bool],$signature);$il=$bridge.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_2);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$sourceType.GetConstructor([type[]]@($sourceArray,[int],[int])))
 if($Write){$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]4);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]5);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]6);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$destinationType.GetConstructor([type[]]@($destinationArray,[int],[int])))};$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]7);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ldelema,[int]);$il.Emit([Reflection.Emit.OpCodes]::Callvirt,$method);$il.Emit([Reflection.Emit.OpCodes]::Ret);$definition=[type]('System.Func`'+($signature.Count+1));return $bridge.CreateDelegate($definition.MakeGenericType([type[]]@($signature+[bool])))
}
function Failure($e){while(($e -is [Management.Automation.RuntimeException] -or $e -is [Reflection.TargetInvocationException]) -and $null -ne $e.InnerException){$e=$e.InnerException};$r=[ordered]@{ok=$false;exception=$e.GetType().FullName;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.EncoderFallbackException]){$r.unknown=[int]$e.CharUnknown;$r.index=$e.Index}elseif($e -is [Text.DecoderFallbackException]){$r.unknownBytes=[int[]]$e.BytesUnknown;$r.index=$e.Index};return $r}

$types=@{Encoder=(CustomType 'Encoder');Decoder=(CustomType 'Decoder')};$bridges=@{Encoder=(Bridge 'Encoder' $true);Decoder=(Bridge 'Decoder' $true)};$templates=@(@(65,66),@(0xD800,0xDC00),@(65,0,66),@(65,0xD800));$inputs=@{Encoder=@(@(),@(65),@(0xDC00),@(0xD800),@(65,0xDC00,66),@(0xDC00,0xDC00),@(0xD800,0xDC00),@(65,0xD800,0xDC00,66),@(65,66,0xDC00));Decoder=@(@(),@(65),@(255),@(240),@(65,255,66),@(255,255),@(240,144,128,128),@(65,240,144,128,128,66),@(65,66,255))};$rows=[Collections.Generic.List[object]]::new()
foreach($direction in @('Encoder','Decoder')){$type=$types[$direction];$buffer=$bufferTypes[$direction];foreach($replacement in $templates){foreach($mode in 0..13){foreach($units in $inputs[$direction]){foreach($capacity in @(0,1,2,3,4,8,12)){foreach($offset in @(0,2)){$provider=[Activator]::CreateInstance($type);$type.GetField('Replacement').SetValue($provider,[string]::new([char[]][int[]]$replacement));$type.GetField('Maximum').SetValue($provider,10);$type.GetField('Mode').SetValue($provider,$mode);$encoding=[Text.Encoding]([Text.UTF8Encoding]::new()).Clone();if($direction -eq 'Encoder'){$encoding.EncoderFallback=$provider;$source=[char[]](@(0xDC00)+[int[]]$units+@(0xD800));$destination=[byte[]]::new($capacity+$offset+2)}else{$encoding.DecoderFallback=$provider;$source=[byte[]](@(255)+[int[]]$units+@(255));$destination=[char[]]::new($capacity+$offset+2)};foreach($name in @('NextCalls','FallbackCalls','RemainingCalls','MoveCalls','ResetCalls')){$buffer.GetField($name).SetValue($null,0)};for($i=0;$i -lt $destination.Length;$i++){$destination[$i]=99};$written=[int[]]@(-7)
try{$success=$bridges[$direction].Invoke($encoding,$source,1,$units.Length,$destination,$offset,$capacity,$written);$result=[ordered]@{ok=$true;success=$success}}catch{$result=Failure $_.Exception}
$rows.Add([ordered]@{direction=$direction;replacementUnits=[int[]]$replacement;mode=$mode;units=[int[]]$units;capacity=$capacity;offset=$offset;result=$result;written=$written[0];destination=[int[]]$destination;factoryCalls=$type.GetField('FactoryCalls').GetValue($provider);bufferCalls=@(foreach($name in @('NextCalls','FallbackCalls','RemainingCalls','MoveCalls','ResetCalls')){[int]$buffer.GetField($name).GetValue($null)})})
}}}}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();rows=$rows.ToArray();qualification='SELECTED_CUSTOM_UTF8_TRY_SPANS_ONLY; ARBITRARY_REENTRANCY_POINTER_LIFETIME_FULL_METADATA_SOURCE_ABI_AND_TASK_ACCEPTANCE_OPEN'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 12 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS custom Encoding Try span controls: $($rows.Count) cases"
